import Foundation
import GRDB

/// Phase 11.1: the single device-local identity used for personalization.
///
/// This is not an account. There is no password, email, token or server. The music library
/// belongs to the installation, not to this profile: no library table references it.
struct LocalUserProfile: Equatable, Sendable, Identifiable {
    /// Stable for the lifetime of the profile; never regenerated by edits.
    let id: UUID
    var username: String
    /// File name of the managed avatar inside `AppStoragePaths.profile`; nil for the default avatar.
    var avatarRelativePath: String?
    let createdAt: Date
    var updatedAt: Date

    var hasCustomAvatar: Bool { avatarRelativePath != nil }

    /// The first grapheme of the username, used by the default avatar's accessibility value.
    var initial: String { username.first.map { String($0).uppercased() } ?? "" }
}

extension LocalUserProfile: FetchableRecord {
    init(row: Row) throws {
        let rawID: String? = row["id"]
        guard let id = rawID.flatMap(UUID.init(uuidString:)) else { throw LocalProfileError.corruptProfile }
        self.id = id
        username = row["username"]
        avatarRelativePath = row["avatarRelativePath"]
        createdAt = row["createdAt"]
        updatedAt = row["updatedAt"]
    }
}

/// Append-only schema. `v023` belonged to the canceled, never-merged Phase 10.8 build and is
/// deliberately skipped (some test phones have it applied; GRDB ignores unknown identifiers).
enum LocalProfileSchema {
    static let version = "v024_local_user_profile"
    static let table = "local_user_profile"

    static func register(in migrator: inout DatabaseMigrator) {
        migrator.registerMigration(version) { db in
            // `slot` is the single-profile guarantee: a primary key that can only ever be 1.
            // There are no foreign keys in either direction; library tables are untouched.
            try db.execute(sql: """
                CREATE TABLE local_user_profile (
                    slot INTEGER PRIMARY KEY NOT NULL CHECK(slot = 1),
                    id TEXT NOT NULL UNIQUE CHECK(length(id) = 36),
                    username TEXT NOT NULL CHECK(length(username) BETWEEN 1 AND \(UsernamePolicy.maximumScalars)),
                    avatarRelativePath TEXT CHECK(avatarRelativePath IS NULL OR (length(avatarRelativePath) BETWEEN 1 AND 128 AND instr(avatarRelativePath, '/') = 0)),
                    createdAt DATETIME NOT NULL,
                    updatedAt DATETIME NOT NULL
                );
                """)
        }
    }
}

/// Display-name rules. A username is never a credential, never unique and never part of a path.
enum UsernamePolicy {
    /// User-perceived characters (grapheme clusters), so "José" and "👨‍👩‍👧" count as people expect.
    static let maximumLength = 30
    /// Hard bound on Unicode scalars, so 30 heavily stacked combining marks cannot grow unbounded.
    static let maximumScalars = 120

    enum Violation: Error, Equatable, Sendable {
        case empty, tooLong, invalidCharacters
        var message: String {
            switch self {
            case .empty: return "Enter a username."
            case .tooLong: return "Use \(UsernamePolicy.maximumLength) characters or fewer."
            case .invalidCharacters: return "Remove line breaks and control characters."
            }
        }
    }

    /// Trimmed, NFC-normalized username, or the first rule it breaks.
    static func validate(_ raw: String) -> Result<String, Violation> {
        let value = raw.trimmingCharacters(in: .whitespacesAndNewlines).precomposedStringWithCanonicalMapping
        guard !value.isEmpty else { return .failure(.empty) }
        let disallowed = value.unicodeScalars.contains { scalar in
            switch scalar.properties.generalCategory {
            case .control, .lineSeparator, .paragraphSeparator, .surrogate, .unassigned: return true
            default: return false
            }
        }
        guard !disallowed else { return .failure(.invalidCharacters) }
        guard value.count <= maximumLength, value.unicodeScalars.count <= maximumScalars else { return .failure(.tooLong) }
        return .success(value)
    }

    static func normalized(_ raw: String) throws -> String {
        switch validate(raw) {
        case .success(let value): return value
        case .failure(let violation): throw LocalProfileError.invalidUsername(violation)
        }
    }
}

enum LocalProfileError: LocalizedError, Equatable, Sendable {
    case invalidUsername(UsernamePolicy.Violation)
    case invalidImage
    case imageTooLarge
    case unsupportedImageDimensions
    case storageUnavailable
    case profileAlreadyExists
    case profileMissing
    case corruptProfile
    case saveFailed

    var errorDescription: String? {
        switch self {
        case .invalidUsername(let violation): return violation.message
        case .invalidImage: return "This photo could not be read. Choose a different image."
        case .imageTooLarge: return "This photo is too large. Choose an image smaller than \(ProfileAvatarProcessor.maximumInputBytes / 1_048_576) MB."
        case .unsupportedImageDimensions: return "This photo's dimensions are not supported. Choose a different image."
        case .storageUnavailable: return "Local storage is unavailable, so your profile can't be read right now. Your music library has not been changed. Try again, or restart Muzik Belesh."
        case .profileAlreadyExists: return "A profile already exists on this iPhone."
        case .profileMissing: return "Your profile could not be found. Try again."
        case .corruptProfile: return "Your saved profile could not be read. Your music library has not been changed."
        case .saveFailed: return "Your profile could not be saved. Nothing was changed. Try again."
        }
    }
}
